//! Timer drivers
//!
//! - [`Timer2`], [`Timer3`]: general-purpose timers (TIM2, TIM3) with
//!   prescaler/period configuration, counter access and update-interrupt
//!   support. Both are generated by the [`impl_timer!`] macro.
//! - [`Timer1Pwm`], [`Timer2Pwm`]: PWM drivers for the full-featured TIM1 and
//!   TIM2 timers (4 channels + break/main-output enable). Both are generated
//!   by the [`impl_timer_pwm!`] macro.
//!
//! # Example
//!
//! ```ignore
//! use ch32x035::{Rcc, Clocks, timer::Timer3};
//!
//! let mut rcc = Rcc::new(dp.RCC);
//! let clocks = Clocks::new(&rcc);
//! let mut tim = Timer3::init(dp.TIM3, &mut rcc, clocks);
//! tim.set_prescaler(47999); // 1 kHz tick @ 48 MHz
//! tim.set_period(999);
//! tim.start();
//! ```

use crate::Steal;
use crate::pac;
use crate::rcc::{Clocks, Rcc};
use crate::reset::Resettable;

/// Generate a general-purpose timer driver (`Timer2`, `Timer3`).
///
/// Uses the registers shared by TIM2 and TIM3: `CTLR1` (CEN), `PSC`, `ATRLR`,
/// `CNT`, `INTFR` (UIF) and `DMAINTENR` (UIE).
macro_rules! impl_timer {
    ($name:ident, $periph:ty, $module:ident) => {
        /// General-purpose timer driver
        pub struct $name {
            tim: $periph,
            #[allow(dead_code)]
            clocks: Clocks,
        }

        impl $name {
            /// Create a new timer driver, resetting and clock-enabling the
            /// peripheral.
            pub fn init(tim: $periph, rcc: &mut Rcc, clocks: Clocks) -> Self {
                tim.init(rcc);
                Self { tim, clocks }
            }

            /// Obtain a handle without ownership checks.
            ///
            /// # Safety
            ///
            /// The caller must ensure the peripheral has been initialized and
            /// that no data races occur.
            #[inline]
            pub unsafe fn steal() -> Steal<Self> {
                Steal(Self {
                    tim: unsafe { <$periph>::steal() },
                    clocks: unsafe { Clocks::steal() },
                })
            }

            /// Set the prescaler value (`PSC`).
            ///
            /// The counter clock is `PCLK1 / (PSC + 1)`.
            pub fn set_prescaler(&mut self, psc: u16) {
                self.tim.psc.write_psc(psc as u32);
            }

            /// Set the auto-reload (period) value (`ATRLR`).
            pub fn set_period(&mut self, period: u16) {
                self.tim.atrlr.write_atrlr(period as u32);
            }

            /// Start the counter.
            pub fn start(&mut self) {
                self.tim.ctlr1.set_cen();
            }

            /// Stop the counter.
            pub fn stop(&mut self) {
                self.tim.ctlr1.clr_cen();
            }

            /// Read the current counter value.
            pub fn count(&self) -> u16 {
                self.tim.cnt.cnt() as u16
            }

            /// Clear the update interrupt flag.
            pub fn clear_update_flag(&mut self) {
                self.tim.intfr.write_bits(pac::$module::Intfr::UIF);
            }

            /// Check whether the update interrupt flag is set.
            pub fn is_update_flag(&self) -> bool {
                self.tim.intfr.read_bits() & pac::$module::Intfr::UIF != 0
            }

            /// Enable the update interrupt.
            pub fn enable_update_interrupt(&mut self) {
                self.tim.dmaintenr.set_uie();
            }

            /// Disable the update interrupt.
            pub fn disable_update_interrupt(&mut self) {
                self.tim.dmaintenr.clr_uie();
            }

            /// Consume the driver and return the underlying peripheral.
            pub fn release(self) -> $periph {
                self.tim
            }
        }
    };
}

impl_timer!(Timer2, pac::TIM2, tim2);
impl_timer!(Timer3, pac::TIM3, tim3);

/// Generate a 4-channel PWM driver for a full-featured timer (TIM1, TIM2).
///
/// Both TIM1 and TIM2 expose the same register layout: `CHCTLR1/2_Output`
/// (OCxM/OCxPE/CCxS), `CCER` (CCxE), `CHxCCR`, `BDTR` (MOE) and the counter
/// group.
macro_rules! impl_timer_pwm {
    ($name:ident, $periph:ty) => {
        /// 4-channel PWM driver for an advanced/general timer
        pub struct $name {
            tim: $periph,
        }

        impl $name {
            /// Create a new PWM driver, resetting and clock-enabling the
            /// peripheral. The counter is configured for PWM with the given
            /// prescaler and auto-reload values.
            pub fn init(tim: $periph, rcc: &mut Rcc, psc: u16, arr: u16) -> Self {
                tim.init(rcc);

                let p = Self { tim };
                // Auto-reload preload enable
                p.tim.ctlr1.set_arpe();
                p.tim.psc.write_psc(psc as u32);
                p.tim.atrlr.write_atrlr(arr as u32);
                p.tim.cnt.write_cnt(0);
                p
            }

            /// Obtain a handle without ownership checks.
            ///
            /// # Safety
            ///
            /// The caller must ensure the peripheral has been initialized and
            /// that no data races occur.
            #[inline]
            pub unsafe fn steal() -> Steal<Self> {
                Steal(Self {
                    tim: unsafe { <$periph>::steal() },
                })
            }

            /// Start the counter (must be called before PWM is output).
            pub fn start(&mut self) {
                self.tim.ctlr1.set_cen();
            }

            /// Stop the counter.
            pub fn stop(&mut self) {
                self.tim.ctlr1.clr_cen();
            }

            /// Set the auto-reload (period) value.
            pub fn set_period(&mut self, arr: u16) {
                self.tim.atrlr.write_atrlr(arr as u32);
            }

            /// Enable PWM output on channel 1 with the given compare value.
            pub fn enable_ch1(&mut self, compare: u16) {
                self.tim.chctlr1_output.write_oc1m(0b110); // PWM mode 1
                self.tim.chctlr1_output.set_oc1pe(); // preload enable
                self.tim.chctlr1_output.write_cc1s(0); // output
                self.tim.ch1cvr.write_ch1cvr(compare as u32);
                self.tim.ccer.set_cc1e();
                self.tim.bdtr.set_moe(); // main output enable
            }

            /// Enable PWM output on channel 2.
            pub fn enable_ch2(&mut self, compare: u16) {
                self.tim.chctlr1_output.write_oc2m(0b110);
                self.tim.chctlr1_output.set_oc2pe();
                self.tim.chctlr1_output.write_cc2s(0);
                self.tim.ch2cvr.write_ch2cvr(compare as u32);
                self.tim.ccer.set_cc2e();
                self.tim.bdtr.set_moe();
            }

            /// Enable PWM output on channel 3.
            pub fn enable_ch3(&mut self, compare: u16) {
                self.tim.chctlr2_output.write_oc3m(0b110);
                self.tim.chctlr2_output.set_oc3pe();
                self.tim.chctlr2_output.write_cc3s(0);
                self.tim.ch3cvr.write_ch3cvr(compare as u32);
                self.tim.ccer.set_cc3e();
                self.tim.bdtr.set_moe();
            }

            /// Enable PWM output on channel 4.
            pub fn enable_ch4(&mut self, compare: u16) {
                self.tim.chctlr2_output.write_oc4m(0b110);
                self.tim.chctlr2_output.set_oc4pe();
                self.tim.chctlr2_output.write_cc4s(0);
                self.tim.ch4cvr.write_ch4cvr(compare as u32);
                self.tim.ccer.set_cc4e();
                self.tim.bdtr.set_moe();
            }

            /// Set the compare value of channel 1.
            pub fn set_ch1_compare(&mut self, compare: u16) {
                self.tim.ch1cvr.write_ch1cvr(compare as u32);
            }

            /// Set the compare value of channel 2.
            pub fn set_ch2_compare(&mut self, compare: u16) {
                self.tim.ch2cvr.write_ch2cvr(compare as u32);
            }

            /// Set the compare value of channel 3.
            pub fn set_ch3_compare(&mut self, compare: u16) {
                self.tim.ch3cvr.write_ch3cvr(compare as u32);
            }

            /// Set the compare value of channel 4.
            pub fn set_ch4_compare(&mut self, compare: u16) {
                self.tim.ch4cvr.write_ch4cvr(compare as u32);
            }

            /// Consume the driver and return the underlying peripheral.
            pub fn release(self) -> $periph {
                self.tim
            }
        }
    };
}

impl_timer_pwm!(Timer1Pwm, pac::TIM1);
impl_timer_pwm!(Timer2Pwm, pac::TIM2);
